def can_finish_dfs(num_courses, prerequisites):
    adj = [[] for _ in range(num_courses)]
    for a, b in prerequisites:
        adj[b].append(a)
    state = [0] * num_courses                              # 0=unvisited, 1=in progress, 2=done
    def has_cycle(u):
        if state[u] == 1:
            return True                                          # revisited on the ACTIVE path: cycle
        if state[u] == 2:
            return False
        state[u] = 1
        for v in adj[u]:
            if has_cycle(v):
                return True
        state[u] = 2
        return False
    for i in range(num_courses):
        if has_cycle(i):
            return False
    return True

