bool canFinish(int numCourses, vector<vector<int>>& prerequisites) {
    vector<vector<int>> adj(numCourses);
    vector<int> indeg(numCourses, 0);
    for (auto& pr : prerequisites) {
        adj[pr[1]].push_back(pr[0]);
        indeg[pr[0]]++;
    }
    queue<int> q;
    for (int i = 0; i < numCourses; i++) if (indeg[i] == 0) q.push(i);              // start with zero in-degree
    int count = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        count++;
        for (int v : adj[u]) {
            if (--indeg[v] == 0) q.push(v);                                            // newly freed up
        }
    }
    return count == numCourses;
}
